<template><section class="mx-auto max-w-2xl space-y-5"><h1 class="text-2xl font-bold text-white">创建广告活动</h1><form class="pc-card space-y-4" @submit.prevent="submit"><input v-model="form.title" class="input-field" required placeholder="Campaign title"/><select v-model="form.listing_id" class="input-field"><option value="">No listing</option><option v-for="item in listings" :key="item.id" :value="item.id">{{ item.title }}</option></select><select v-model="form.placement" class="input-field"><option value="SEARCH">Search</option><option value="MARKETPLACE">Marketplace</option></select><input v-model.number="budget" class="input-field" type="number" min="1" step="0.01" placeholder="Budget"/><input v-model.number="bid" class="input-field" type="number" min="0.01" step="0.01" placeholder="Bid per click"/><button class="btn-primary">Create draft</button><p v-if="error" class="text-red-300">{{ error }}</p></form></section></template>
<script setup lang="ts">definePageMeta({layout:'procurement',middleware:['auth']});const api=useCommerce();const {apiFetch}=useApi();const listings=ref<any[]>([]);const budget=ref(100);const bid=ref(1);const error=ref('');const form=reactive({title:'',listing_id:'',placement:'MARKETPLACE',currency:'USD'});async function submit(){try{await apiFetch('/cebu-trade/ads/campaigns',{method:'POST',body:{...form,listing_id:form.listing_id||null,budget_minor:Math.round(budget.value*100),bid_per_click_minor:Math.round(bid.value*100)}});await navigateTo('/supplier/ads')}catch(e:any){error.value=e?.data?.detail||e?.message}}onMounted(async()=>listings.value=(await api.listSupplierListings('active')).items)</script>
